item.content:encoded:
/* ===== FFood – ajustes estéticos ===== */
.has-text-align-center{text-align:center!important}
#reviews h2,#whyus h2,#whyus h3,#contact h2{text-align:center}
#contact .rtb-booking-form form{background:none;box-shadow:none;padding:0;margin:0}
.wp-block-heading.has-text-align-center{margin-left:auto;margin-right:auto}
/* Tarjetas con sombra suave */
#reviews .wp-block-column,#whyus .wp-block-column{box-shadow:0 8px 24px rgba(43,58,47,.08);transition:transform .25s ease,box-shadow .25s ease}
#reviews .wp-block-column:hover,#whyus .wp-block-column:hover{transform:translateY(-4px);box-shadow:0 14px 32px rgba(43,58,47,.14)}
#whyus .wp-block-column{background:#FBF8F2;border-radius:16px;padding:32px 28px}
/* Botones */
.wp-block-button__link{font-weight:700;padding:14px 30px;transition:all .2s ease}
.wp-block-button__link:hover{transform:translateY(-2px)}
/* Formulario de reservas en tarjeta blanca */
#contact .rtb-booking-form{background:#fff;border-radius:20px;padding:32px;box-shadow:0 20px 40px rgba(0,0,0,.2);max-width:760px;margin:32px auto 0}
#contact .rtb-booking-form fieldset{border:0;padding:0}
#contact .rtb-booking-form legend,#contact .rtb-booking-form label{color:#2B3A2F!important;font-weight:700}
#contact .rtb-booking-form input,#contact .rtb-booking-form select,#contact .rtb-booking-form textarea{border:1px solid #E5DCC8;border-radius:10px;padding:10px 14px}
#contact .rtb-booking-form button{background:#4F7A5E;color:#fff;border-radius:50px;padding:14px 34px;font-weight:700;border:0}
/* Cabecera */
.main-header-menu .menu-link{font-weight:600}
.main-header-menu .menu-link:hover{color:#4F7A5E!important}

/* Hero: dejar sitio a la cabecera transparente */
.entry-content > .wp-block-cover:first-child{padding-top:250px!important;padding-bottom:100px!important}


/* ===== Página Carta ===== */
.ff-carta-hero{padding-top:250px!important}

.ff-plato{padding:18px 0;border-bottom:1px solid #E5DCC8}
.ff-plato:last-child{border-bottom:0}
.ff-plato-top{gap:16px;align-items:baseline}
.ff-plato-top p{margin:0}
.ff-plato-nombre{font-family:'Playfair Display',serif;font-size:20px;color:#2B3A2F}
.ff-precio{font-weight:700;color:#4F7A5E;white-space:nowrap;font-size:18px}
.ff-plato-desc{margin:6px 0 0!important;font-size:15px;color:#5A5A4E}
.ff-cat h2{text-align:center}

/* Cabecera fija en páginas sin cabecera transparente */
.ast-primary-header-bar{border-bottom:1px solid #E5DCC8}

.ast-primary-header-bar .main-header-menu .menu-link{color:#2B3A2F!important}
.ast-primary-header-bar .main-header-menu .current-menu-item>.menu-link,.ast-primary-header-bar .main-header-menu .menu-link:hover{color:#4F7A5E!important}
.ast-primary-header-bar .ast-custom-button{background:#4F7A5E!important;color:#fff!important;border-color:#4F7A5E!important}
.ast-primary-header-bar .ast-custom-button:hover{background:#3E6249!important}
.ff-plato-img img{width:100%;height:auto;border-radius:16px}

/* Pie y barra lateral */
.site-primary-footer-wrap .ff-footer-firma{color:#F7F2E9;font-family:"Playfair Display",serif;font-size:20px;margin:0}
.site-primary-footer-wrap{padding:28px 0}
#secondary .wp-block-search__button{background:#4F7A5E;color:#fff;border-radius:50px;border:0}
#secondary .wp-block-search__input{border:1px solid #E5DCC8;border-radius:10px}
#secondary .wp-block-latest-posts li{margin-bottom:14px;overflow:hidden}
#secondary .wp-block-latest-posts__featured-image img{border-radius:8px}
#secondary h2,#secondary h3,#secondary .wp-block-search__label{font-family:"Playfair Display",serif;font-size:20px;font-weight:700}

/* Selector de idioma GTranslate en el menú */
.main-header-menu li.menu-item-gtranslate{display:flex;align-items:center;margin-left:8px}
.main-header-menu li.menu-item-gtranslate [class^="gt_container"],.main-header-menu li.menu-item-gtranslate [class*=" gt_container"]{position:relative!important;top:auto!important;left:auto!important}
.main-header-menu li.menu-item-gtranslate .gt_float_switcher{box-shadow:none;background:transparent;font-size:14px}
/* WPForms y encuesta */
.ff-form-contacto .wpforms-container{background:#fff;border-radius:20px;padding:32px;box-shadow:0 12px 32px rgba(43,58,47,.1)}
.ff-form-contacto .wpforms-submit{background:#4F7A5E!important;border-radius:50px!important;padding:12px 32px!important}
.ff-encuesta .wp-polls{background:#fff;border-radius:20px;padding:28px;box-shadow:0 12px 32px rgba(43,58,47,.1)}
.ff-encuesta .wp-polls .Buttons{background:#4F7A5E;color:#fff;border:0;border-radius:50px;padding:10px 26px;cursor:pointer}
.ff-encuesta .wp-polls ul li{list-style:none}

/* RSS: icono en el pie y feeds externos */
.site-primary-footer-wrap .ff-rss{margin-top:12px}
.site-primary-footer-wrap .ff-rss .wp-social-link{background:#E5DCC8!important;color:#2B3A2F!important}
.site-primary-footer-wrap .ff-rss .wp-social-link a{color:#2B3A2F!important;font-weight:700}
#secondary .ff-rss-externos h4{font-family:"Playfair Display",serif;font-size:17px;margin:18px 0 6px}
#secondary .ff-rss-externos h4 a{color:#2B3A2F}
#secondary .wp-block-rss{margin:0;padding:0}
#secondary .wp-block-rss li{list-style:none;margin:0 0 8px;font-size:15px;line-height:1.4}
#secondary .wp-block-rss time{display:block;font-size:13px;color:#5A5A4E}

.site-primary-footer-wrap .ff-footer-firma{text-align:center!important}

/* ================= RESPONSIVE ================= */
img,iframe,video{max-width:100%}
html,body{overflow-x:hidden}
.wp-block-button__link:not(.has-text-color){color:#fff}
.entry-content h1,.entry-content h2,.entry-content h3{overflow-wrap:break-word}
.entry-content h2.wp-block-heading{font-size:clamp(28px,2.4vw + 16px,48px);line-height:1.2}
.entry-content > .wp-block-cover:first-child h1{text-align:center}
.ff-plato-top .ff-plato-nombre{min-width:0}
.single-plato .wp-block-table{overflow-x:auto}

/* Tablet */
@media (max-width:921px){
 .entry-content > .wp-block-cover:first-child{padding-top:80px!important;padding-bottom:72px!important;min-height:auto!important}
 .entry-content > .wp-block-cover:first-child h1{font-size:44px!important}
 .ff-carta-hero{padding-top:80px!important;padding-bottom:64px!important}
 .ff-carta-hero h1{font-size:44px!important}
 .entry-content > .wp-block-group.alignfull{padding-top:64px!important;padding-bottom:64px!important}
 #services .wp-block-columns{flex-wrap:wrap!important}
 #services .wp-block-column{flex-basis:calc(50% - 12px)!important}
 .site-title{display:block!important}
 .site-title a{font-size:26px}
 .ast-mobile-menu-trigger-minimal,.menu-toggle{color:#2B3A2F!important;fill:#2B3A2F!important}
 .ast-mobile-menu-trigger-minimal svg,.menu-toggle svg{fill:#2B3A2F!important;width:26px;height:26px}
 .custom-logo-link img{max-width:64px;height:auto}
 .ast-mobile-header-wrap .main-header-menu .menu-link{color:#2B3A2F!important;border-bottom:1px solid #E5DCC8}
 .ast-mobile-header-wrap .ast-builder-menu-mobile,.ast-mobile-header-content{background:#FBF8F2!important}
 .ast-mobile-header-content .ast-custom-button{background:#4F7A5E!important;color:#fff!important}
 .elementor-92 .e-con-full,.elementor-92 .e-con{--flex-wrap:wrap}
}

/* Móvil */
@media (max-width:767px){
 body{font-size:16px}
 .entry-content > .wp-block-cover:first-child{padding:56px 16px 56px!important}
 .entry-content > .wp-block-cover:first-child h1,.ff-carta-hero h1{font-size:34px!important;line-height:1.2!important}
 .entry-content > .wp-block-cover:first-child p{font-size:16px!important}
 .entry-content > .wp-block-cover:first-child .wp-block-buttons{flex-direction:column;align-items:stretch}
 .entry-content > .wp-block-cover:first-child .wp-block-button,.entry-content > .wp-block-cover:first-child .wp-block-button__link{width:100%;text-align:center}
 .ff-carta-hero{padding:56px 16px 48px!important}
 .entry-content > .wp-block-group.alignfull{padding:48px 20px!important}
 .entry-content h2.wp-block-heading{font-size:28px!important}
 .entry-content h3.wp-block-heading{font-size:20px!important}
 .wp-block-columns{gap:16px!important}
 #services .wp-block-column{flex-basis:100%!important}
 #services .wp-block-column,#reviews .wp-block-column,#whyus .wp-block-column{padding:24px 20px!important}
 #services .wp-block-column p[style*="font-size:40px"],#whyus .wp-block-column p[style*="font-size:40px"]{font-size:32px!important;margin-bottom:4px}
 #about .wp-block-group{padding:28px 24px!important}
 #about h3[style*="font-size:56px"]{font-size:42px!important}
 .ff-plato{padding:14px 0}
 .ff-plato-nombre{font-size:17px!important}
 .ff-precio{font-size:16px!important}
 .ff-mapa iframe{height:300px}
 #contact .rtb-booking-form,.ff-encuesta .wp-polls{padding:20px!important}
 .rtb-booking-form input,.rtb-booking-form select,.rtb-booking-form textarea{width:100%!important;max-width:100%!important;box-sizing:border-box}
 .wpforms-container .wpforms-field input,.wpforms-container .wpforms-field textarea{max-width:100%!important}
 .wpforms-container .wpforms-field-row .wpforms-one-half{width:100%!important;margin-left:0!important;float:none!important;margin-bottom:10px}
 .ast-separate-container .ast-article-post,.ast-separate-container .ast-article-single{padding:24px 18px!important}
 .site-primary-footer-wrap .ff-footer-firma{font-size:17px}
 .elementor-92 .e-con{--flex-direction:column!important;flex-direction:column!important}
 .elementor-92 .e-con > .e-con{--width:100%!important;width:100%!important}
 .elementor-92 > .e-con:first-child{--padding-top:56px!important;padding-top:56px!important}
 .elementor-92 h1.elementor-heading-title{font-size:36px!important}
 .elementor-92 h2.elementor-heading-title{font-size:28px!important}
 .elementor-92 .elementor-counter-number-wrapper{font-size:40px!important}
}

@media (max-width:921px){.ast-mobile-header-content .menu-item-gtranslate{padding:12px 20px}.ast-mobile-header-content .menu-item-gtranslate [class*="gt_container"]{position:relative!important}}

.ff-lang-mobile{display:none;justify-content:center;margin-top:14px}
@media (max-width:921px){.ff-lang-mobile{display:flex}.ff-lang-mobile .gt_float_switcher{box-shadow:none}.ast-mobile-header-content .main-header-menu .menu-link{padding-left:20px!important;padding-right:20px!important}.ast-mobile-header-content .ast-builder-button-wrap{padding:16px 20px}}

@media (max-width:767px){.elementor-92 > .e-con:first-child .elementor-widget-heading:first-child .elementor-heading-title{font-size:13px!important;letter-spacing:3px}}
.page-id-92 .entry-header{display:none}

@media (max-width:767px){.wpforms-container .wpforms-field-row .wpforms-field-row-block{width:100%!important;padding:0!important;margin:0 0 10px!important;float:none!important}}

/* ===== Selector de idioma personalizado ===== */
.gt_float_switcher{background:transparent!important;box-shadow:none!important;font-family:'Lato',sans-serif!important;font-size:14px!important;color:#2B3A2F!important;border-radius:50px!important;overflow:visible!important}
.gt_float_switcher .gt-selected{background:transparent!important;border:1.5px solid #4F7A5E;border-radius:50px;transition:background .2s}
.gt_float_switcher .gt-selected:hover{background:#F7F2E9!important}
.gt_float_switcher .gt-selected .gt-current-lang{padding:7px 14px!important;display:flex!important;align-items:center;gap:8px;color:#2B3A2F!important;font-weight:700!important}
.gt_float_switcher img{width:20px!important;height:20px!important;border-radius:50%;object-fit:cover;margin:0!important}
.gt_float_switcher .gt-lang-code{font-size:13px;letter-spacing:1px;text-transform:uppercase;color:#2B3A2F}
.gt_float_switcher .gt_float_switcher-arrow{width:10px!important;height:10px!important;margin-left:0!important;opacity:.7;filter:brightness(0) saturate(100%) invert(19%) sepia(10%) saturate(1200%) hue-rotate(85deg)}
.gt_float_switcher .gt_options{position:absolute!important;top:calc(100% + 8px);right:0;min-width:150px;background:#FBF8F2!important;border:1px solid #E5DCC8;border-radius:14px;box-shadow:0 12px 28px rgba(43,58,47,.15);padding:6px!important;z-index:999}
.gt_float_switcher .gt_options a{display:flex!important;align-items:center;gap:10px;padding:9px 12px!important;border-radius:10px;color:#2B3A2F!important;font-size:14px!important;font-weight:600}
.gt_float_switcher .gt_options a:hover{background:#E5DCC8!important;color:#2B3A2F!important}
.gt_float_switcher .gt_options a.gt-current{display:none!important}
.ff-lang-mobile .gt_options{top:auto!important;bottom:calc(100% + 8px);left:50%;right:auto;transform:translateX(-50%)}
.site-primary-footer-wrap .ff-lang-mobile .gt-selected{border-color:#E5DCC8}
.site-primary-footer-wrap .ff-lang-mobile .gt-current-lang,.site-primary-footer-wrap .ff-lang-mobile .gt-lang-code{color:#F7F2E9!important}
.site-primary-footer-wrap .ff-lang-mobile .gt-selected:hover{background:rgba(255,255,255,.08)!important}
.site-primary-footer-wrap .ff-lang-mobile .gt_float_switcher-arrow{filter:brightness(0) invert(1)}

.gt_float_switcher{position:relative!important}
.main-header-menu .gt_float_switcher .gt_options{top:44px!important}
.gt_float_switcher .gt_float_switcher-arrow{transform:rotate(0deg)!important;transition:transform .2s}
.gt_float_switcher .gt_float_switcher-arrow.gt_arrow_rotate{transform:rotate(180deg)!important}
.ff-lang-mobile .gt_float_switcher .gt_float_switcher-arrow{transform:rotate(180deg)!important}
.ff-lang-mobile .gt_float_switcher .gt_float_switcher-arrow.gt_arrow_rotate{transform:rotate(0deg)!important}

/* Botón de idioma: conmutador directo y centrado */
.gt_float_switcher .gt_options{display:none!important}
.gt_float_switcher .gt_float_switcher-arrow{display:none!important}
.gt_float_switcher .gt-selected{cursor:pointer;user-select:none}
.gt_float_switcher .gt-selected .gt-current-lang{padding:7px 16px!important;justify-content:center}
.gt_float_switcher .gt-selected:focus-visible{outline:2px solid #4F7A5E;outline-offset:2px}
.main-header-menu li.menu-item-gtranslate{align-self:center!important;display:flex!important;align-items:center!important;height:auto!important;padding:0!important;margin:0 4px 0 12px!important}
.main-header-menu li.menu-item-gtranslate > [class*="gt_container"],.main-header-menu li.menu-item-gtranslate > [class*="gt_container"] > div{display:flex!important;align-items:center;justify-content:center;line-height:1}
.main-header-menu li.menu-item-gtranslate .gt_float_switcher{display:flex;align-items:center;margin:0!important}
.ff-lang-mobile{justify-content:center!important;align-items:center}
.ff-lang-mobile > *{margin-left:auto;margin-right:auto}

/* ===== Página Suscríbete (RSS) ===== */
.ff-pasos{max-width:560px;margin:24px auto!important;padding-left:1.4em}
.ff-pasos li{margin-bottom:10px}
.ff-feed-box{display:flex;align-items:center;gap:12px;background:#fff;border:1.5px solid #E5DCC8;border-radius:50px;padding:8px 8px 8px 22px;max-width:620px;margin:28px auto 16px;box-shadow:0 8px 24px rgba(43,58,47,.08)}
.ff-feed-box code{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:none;color:#2B3A2F;font-size:15px;padding:0}
.ff-copy{background:#4F7A5E;color:#fff;border:0;border-radius:50px;padding:10px 24px;font-weight:700;cursor:pointer;white-space:nowrap}
.ff-copy:hover{background:#3E6249}
.ff-feed-xml{font-size:14px;color:#5A5A4E}
.ff-ultimas{margin-top:32px!important}
.ff-ultimas li{background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 8px 24px rgba(43,58,47,.08);padding:0 0 18px!important}
.ff-ultimas .wp-block-latest-posts__featured-image img{width:100%;height:180px;object-fit:cover}
.ff-ultimas a.wp-block-latest-posts__post-title,.ff-ultimas time,.ff-ultimas .wp-block-latest-posts__post-excerpt{display:block;padding:0 18px}
.ff-ultimas a.wp-block-latest-posts__post-title{font-family:'Playfair Display',serif;font-weight:700;font-size:19px;color:#2B3A2F;margin-top:14px}
.ff-ultimas time{font-size:13px;color:#4F7A5E;margin:4px 0 8px}
.ff-ultimas .wp-block-latest-posts__post-excerpt{font-size:15px;margin:0}
@media (max-width:767px){.ff-feed-box{flex-direction:column;border-radius:18px;padding:16px;align-items:stretch;text-align:center}.ff-feed-box code{white-space:normal;word-break:break-all}.ff-ultimas li{margin-bottom:16px!important}}

.ff-ultimas{display:grid!important;grid-template-columns:repeat(3,1fr);gap:24px;padding:0!important;list-style:none}
.ff-ultimas li{margin:0!important}
@media (max-width:921px){.ff-ultimas{grid-template-columns:repeat(2,1fr)}}
@media (max-width:600px){.ff-ultimas{grid-template-columns:1fr}}

/* ===== Noticias: rejilla adaptable al número de entradas ===== */
.blog #main > .ast-row,.archive #main > .ast-row{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px;margin:0!important;align-items:start}
.blog #main > .ast-row > article,.archive #main > .ast-row > article{width:auto!important;max-width:none!important;padding:0!important;margin:0!important;flex:none!important}
.blog #main .ast-article-inner,.archive #main .ast-article-inner{height:100%}
/* 1 sola noticia, o la primera cuando hay un número impar: tarjeta destacada a todo el ancho */
.blog #main > .ast-row > article:first-child:nth-last-child(odd),.archive #main > .ast-row > article:first-child:nth-last-child(odd){grid-column:1 / -1}
@media (min-width:768px){
 .blog #main > .ast-row > article:first-child:nth-last-child(odd) .post-content,.archive #main > .ast-row > article:first-child:nth-last-child(odd) .post-content{display:grid;grid-template-columns:1.15fr 1fr;column-gap:32px;align-items:center;padding-right:32px}
 .blog #main > .ast-row > article:first-child:nth-last-child(odd) .ast-blog-featured-section,.archive #main > .ast-row > article:first-child:nth-last-child(odd) .ast-blog-featured-section{grid-row:1 / span 6;margin:0!important;height:100%}
 .blog #main > .ast-row > article:first-child:nth-last-child(odd) .ast-blog-featured-section img,.archive #main > .ast-row > article:first-child:nth-last-child(odd) .ast-blog-featured-section img{height:100%;min-height:320px;object-fit:cover;width:100%}
 .blog #main > .ast-row > article:first-child:nth-last-child(odd) .ast-blog-featured-section ~ *,.archive #main > .ast-row > article:first-child:nth-last-child(odd) .ast-blog-featured-section ~ *{grid-column:2}
 .blog #main > .ast-row > article:first-child:nth-last-child(odd) .entry-title,.archive #main > .ast-row > article:first-child:nth-last-child(odd) .entry-title{font-size:30px!important}
}
.blog #main .ast-blog-featured-section img,.archive #main .ast-blog-featured-section img{width:100%;height:220px;object-fit:cover}
/* 7 o más noticias: 3 columnas para no alargar la página */
@media (min-width:1100px){.blog #main > .ast-row:has(> article:nth-child(7)),.archive #main > .ast-row:has(> article:nth-child(7)){grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:767px){.blog #main > .ast-row,.archive #main > .ast-row{grid-template-columns:1fr}}
/* Barra lateral más ligera en Noticias */
.blog #secondary .widget:has(.wp-block-latest-posts){display:none}
#secondary .widget{margin-bottom:28px}
#secondary .ff-rss-externos .wp-block-rss li{margin-bottom:6px;font-size:14px}
@media (min-width:922px){.blog #secondary .sidebar-main,.archive #secondary .sidebar-main{position:sticky;top:24px}}

/* Botón enviar del formulario de reservas (todas las páginas) */
.rtb-booking-form .rtb-form-submit button,.rtb-booking-form button[type=submit]{background:#4F7A5E!important;color:#FFFFFF!important;border:0!important;border-radius:50px!important;padding:14px 36px!important;font-weight:700!important;font-size:16px!important;cursor:pointer;transition:background .2s,transform .2s}
.rtb-booking-form .rtb-form-submit button:hover,.rtb-booking-form .rtb-form-submit button:focus,.rtb-booking-form button[type=submit]:hover{background:#3E6249!important;color:#FFFFFF!important;transform:translateY(-2px)}
.rtb-booking-form .rtb-form-submit button:focus-visible{outline:2px solid #2B3A2F;outline-offset:3px}
@media (max-width:767px){.rtb-booking-form .rtb-form-submit button{width:100%}}

/* Formulario de reservas con el mismo estilo en todas las páginas */
.rtb-booking-form{background:#fff;border-radius:20px;padding:32px;box-shadow:0 20px 40px rgba(43,58,47,.12);max-width:760px;margin:32px auto 0}
.rtb-booking-form form{background:none!important;box-shadow:none!important;padding:0!important;margin:0!important}
.rtb-booking-form fieldset{border:0!important;padding:0!important;margin:0 0 20px!important}
.rtb-booking-form legend{font-family:'Playfair Display',serif;font-size:20px;font-weight:700;color:#2B3A2F!important;padding:0;margin-bottom:12px}
.rtb-booking-form label{color:#2B3A2F!important;font-weight:700}
.rtb-booking-form input:not([type=checkbox]):not([type=radio]),.rtb-booking-form select,.rtb-booking-form textarea{width:100%!important;max-width:100%!important;box-sizing:border-box;border:1px solid #E5DCC8!important;border-radius:10px!important;padding:10px 14px!important;background:#FBF8F2}
.rtb-booking-form .add-message a{color:#4F7A5E;font-weight:700;text-transform:none}
@media (max-width:767px){.rtb-booking-form{padding:20px}}

.rtb-booking-form{margin-bottom:48px!important}
